/// Report the Custos capabilities the *configured* PDS advertises, so the create flow can
/// refuse honestly and early instead of failing deep inside the ceremony.
///
/// Creating a brand-new identity is Custos-structural, not merely Custos-flavored: the
/// genesis op has to carry rotation keys the wallet authored, and `createAccount` gives a
/// client no way to express that. Only a host offering the `/v1/*` ceremony can do it. So
/// the wallet asks the host what it offers rather than discovering the answer as an opaque
/// error three screens later, after the user has typed a claim code, an email, and a handle.
///
/// An absent `custos` object yields an empty list. That is deliberate and is what every
/// spec-compliant PDS returns; a host that does not say it can run the ceremony is treated
/// as unable to, never as a Custos that merely went unasked.
#[tauri::command]
async fn get_custos_capabilities(
    state: tauri::State<'_, oauth::AppState>,
) -> Result<Vec<String>, String> {
    Ok(describe_configured_server(&state)
        .await?
        .custos
        .map(|c| c.capabilities)
        .unwrap_or_default())
}

/// Shared `describeServer` fetch against the configured PDS.
///
/// Rejects with a message string on network/HTTP/parse failure so each caller surfaces the
/// same reachability verdict; neither caller may silently substitute a default for an
/// unreachable host, which would let the capability gate answer "no Custos here" when the
/// truth is "could not ask".
async fn describe_configured_server(
    state: &tauri::State<'_, oauth::AppState>,
) -> Result<DescribeServerResponse, String> {
    let resp = state

    resp.json()
        .await
        .map_err(|e| format!("failed to parse describeServer response: {e}"))
}

/// Return the saved PDS base URL, or `None` if not yet configured.

